</main><footer>ResolveEd • School Problem Resolution Effectiveness System</footer><script>function openLogoutModal(e){e.preventDefault();document.getElementById('logoutModal').classList.remove('hidden')}function closeLogoutModal(){document.getElementById('logoutModal').classList.add('hidden')} function openDeleteModal(id,title){document.getElementById('deleteReportId').value=id;document.getElementById('deleteMessage').textContent='Are you sure you want to delete “'+title+'”? This action cannot be undone.';document.getElementById('deleteModal').classList.remove('hidden')} function closeDeleteModal(){document.getElementById('deleteModal').classList.add('hidden')}</script></body></html>
